solution:
extern "C" {
  fn abs(x: Int) -> Int;
  fn sqrt(x: Float64) -> Float64;
}

fn safe_abs(x: Int) -> Result[Int, Str] {
  return Ok(abs(x));
}

fn safe_sqrt(x: Float64) -> Result[Float64, Str] {
  if x < 0.0 { return Err("Negative input"); }
  return Ok(sqrt(x));
}

fn main() -> Int {
  match safe_abs(-42) {
    Ok(val) => { return val; }
    Err(_) => { return 0; }
  }
}
